'use client';

import * as React from 'react';
import { Button as BaseButton } from '@base-ui/react/button';
import './button.css';

/**
 * Which cap the button wears. `standard` is soft-touch in the colorway,
 * `primary` is the dark cap, and `destructive` is the one red cap. Use at
 * most one primary or destructive cap per group.
 */
export type ButtonCap = 'standard' | 'primary' | 'destructive';

export interface ButtonProps extends BaseButton.Props {
  cap?: ButtonCap;
  /** default: 32 tall. compact: 28, 12 pt, raise-sm (the medium's pills: "seed a sample day", "lenses ⌘K"). */
  size?: 'default' | 'compact';
}

/**
 * A press-in pill button (KAMUI-15). While held it sinks 1px and its shadow
 * collapses into a well; on release it springs back. MetalUI icons inside it
 * play their hover pose and press one-shot from the whole button.
 */
export const Button = React.forwardRef<HTMLElement, ButtonProps>(function Button(
  { cap = 'standard', size = 'default', className, ...props },
  ref,
) {
  return (
    <BaseButton
      ref={ref}
      data-cap={cap}
      data-size={size}
      className={(state) => {
        const extra = typeof className === 'function' ? className(state) : className;
        return extra ? `mu-button mu-icon-trigger ${extra}` : 'mu-button mu-icon-trigger';
      }}
      {...props}
    />
  );
});

@import "../tokens.css";

/* KAMUI-15 · Button. Values are tokens.json button (the sheet's .btn, refit to the height ladder).
   --mu-button-h and --mu-button-px override one instance (the docs dials). */
.mu-button {
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--mu-button-gap);
  height: var(--mu-button-h, var(--mu-button-height));
  margin: 0;
  padding: 0 var(--mu-button-px, var(--mu-button-pad));
  border: 0;
  border-radius: var(--mu-radius-pill);
  font: var(--mu-type-ui);
  letter-spacing: var(--mu-type-ui-tracking);
  white-space: nowrap;
  color: var(--mu-ink);
  background: var(--mu-btn-bg);
  box-shadow: var(--mu-btn-sh);
  cursor: pointer;
  user-select: none;
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  transition:
    transform var(--mu-spring-release-d) var(--mu-spring-release),
    box-shadow var(--mu-button-fade-ms),
    background var(--mu-button-fade-ms),
    color var(--mu-button-fade-ms);
}
.mu-button > svg { width: var(--mu-button-glyph); height: var(--mu-button-glyph); flex: none; }

.mu-button:active:not([data-disabled]) {
  transform: translateY(var(--mu-button-travel));
  /* Down in 50 ms, linear; back on release. */
  transition-duration: var(--mu-button-press-ms);
  transition-timing-function: linear;
  background: var(--mu-pressed-bg);
  box-shadow: var(--mu-pressed-sh);
}

.mu-button[data-cap="primary"] {
  color: var(--mu-primary-ink);
  background: var(--mu-primary-bg);
  box-shadow: var(--mu-primary-sh);
}
.mu-button[data-cap="primary"]:active:not([data-disabled]) {
  background: var(--mu-primary-pressed-bg);
  box-shadow: var(--mu-primary-pressed-sh);
}

.mu-button[data-cap="destructive"] {
  color: var(--mu-destructive-ink);
  background: var(--mu-destructive-bg);
  box-shadow: var(--mu-destructive-sh);
}
.mu-button[data-cap="destructive"]:active:not([data-disabled]) {
  background: var(--mu-destructive-pressed-bg);
  box-shadow: var(--mu-destructive-pressed-sh);
}

.mu-button:focus-visible {
  outline: var(--mu-button-focus-width) solid var(--mu-focus);
  outline-offset: var(--mu-button-focus-offset);
}

.mu-button[data-disabled] {
  opacity: var(--mu-button-disabled);
  cursor: default;
}

/* Compact: the medium's pills, 28 on the height ladder. The button fill on raise-sm, ink2 until hover. */
.mu-button[data-size="compact"] {
  gap: var(--mu-button-compact-gap);
  height: var(--mu-button-h, var(--mu-button-compact-height));
  padding: 0 var(--mu-button-px, var(--mu-button-compact-pad));
  font-size: var(--mu-button-compact-size);
}
.mu-button[data-size="compact"] > svg { width: var(--mu-button-compact-glyph); height: var(--mu-button-compact-glyph); }
.mu-button[data-size="compact"][data-cap="standard"] { color: var(--mu-ink2); box-shadow: var(--mu-raise-sm); }
.mu-button[data-size="compact"][data-cap="standard"]:hover:not([data-disabled]) { color: var(--mu-ink); }
.mu-button[data-size="compact"][data-cap="standard"]:active:not([data-disabled]) { box-shadow: var(--mu-pressed-sh); }

/* Reduce Motion: the press rides release, which the policy keeps unchanged (tokens.json
   springs.release.reduced). One point of travel with no overshoot is feedback, not decoration. */
